        (json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"": "x"}}), "InvalidParameterValue"),
        (json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": 1}}), "InvalidParameterValue"),
        (json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": null}}), "InvalidParameterValue"),
        (json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "é".repeat(129)}}), "InvalidParameterValue"),
        (json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"k".repeat(129): "x"}}), "InvalidParameterValue"),
