        (json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {}}), "QueueDoesNotExist"),
        (json!({"Command": "UntagQueue", "QueueName": "nope", "TagKeys": []}), "QueueDoesNotExist"),
