        (json!({"QueueName": "q", "Entries": [{"Id": 1, "Body": "x"}]}), "InvalidBatchEntryId"),
        (json!({"QueueName": "q", "Entries": [{"Id": "a b", "Body": "x"}]}), "InvalidBatchEntryId"),
